package com.videokit.d1input;
import androidx.media3.datasource.*;import androidx.media3.extractor.*;import com.videokit.spike.c14.*;
import java.io.*;import java.nio.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import static com.videokit.d1input.InputSinkCheck.*;
/** Tester-owned boundary evidence, real DefaultExtractorInput; no container/parser standins. */
public class IndependentContainer02BoundaryCheck {
 static int cases;static void pass(String name){cases++;System.out.println("PASS independent_container "+name);}
 static void peek()throws Exception{Source h=new Source(7L);h.chunk=3;HostInputFactory f=factory(h);HostDataSource ds=f.createDataSource();ds.open(new DataSpec(f.uri()));HostMp4Inspection.Reader r=new HostMp4Inspection.Reader(ds);DefaultExtractorInput in=new DefaultExtractorInput(r,0,7);byte[] peek=new byte[3],all=new byte[7];try{in.peekFully(peek,0,3);need(in.getPosition()==0&&in.getPeekPosition()==3,"real peek distinct from logical position");in.resetPeekPosition();in.readFully(all,0,7);for(int i=0;i<7;i++)need(all[i]==value(i),"real bytes after peek reset");need(r.readBytes==7&&in.getPosition()==7&&!in.readFully(new byte[1],0,1,true)&&h.offsets.equals(List.of(0L,3L,6L)),"peek not duplicate physical budget");}finally{close(ds,f);}pass("real_peek_reset_shortread_EOF_budget");}
 static void cumulative()throws Exception{long size=6L*1024*1024;Source h=new Source(size);HostInputFactory f=factory(h);HostDataSource ds=f.createDataSource();ds.open(new DataSpec(f.uri()));HostMp4Inspection.Reader r=new HostMp4Inspection.Reader(ds);byte[] block=new byte[65536];try{DefaultExtractorInput in=new DefaultExtractorInput(r,0,size);for(int i=0;i<64;i++)need(in.read(block,0,block.length)==block.length,"first bounded pass");ds.close();ds.open(new DataSpec(f.uri()));in=new DefaultExtractorInput(r,0,size);for(int i=0;i<64;i++)need(in.read(block,0,block.length)==block.length,"same Reader reopened second pass");int calls=h.offsets.size();DefaultExtractorInput target=in;block[0]=99;rejected(()->target.read(block,0,1),"MP4_INPUT_BYTE_BUDGET");need(r.readBytes==8388608&&in.getPosition()==4194304&&h.offsets.size()==calls&&calls==128&&block[0]==99&&h.opens.get()==2,"cumulative8MiB across reads not per range, no new host/caller mutation");}finally{close(ds,f);}pass("8MiB_cumulative_across_reopen_rejected_before_host");}
 static void absolute()throws Exception{Source h=new Source(73L);HostInputFactory f=factory(h);HostDataSource ds=f.createDataSource();long remaining=ds.open(new DataSpec(f.uri(),5,-1));DefaultExtractorInput in=new DefaultExtractorInput(new HostMp4Inspection.Reader(ds),5,5+remaining);try{byte[] b=new byte[3];in.readFully(b,0,3);need(remaining==68&&in.getPosition()==8&&in.getLength()==73&&b[0]==value(5),"absolute end differs from remaining");}finally{close(ds,f);}Source u=new Source(null);f=factory(u);ds=f.createDataSource();remaining=ds.open(new DataSpec(f.uri(),2,-1));in=new DefaultExtractorInput(new HostMp4Inspection.Reader(ds),2,remaining);try{byte[] b=new byte[3];in.readFully(b,0,3);need(in.getPosition()==5&&in.getLength()==-1&&!in.readFully(new byte[1],0,1,true),"unknown range length remains -1");}finally{close(ds,f);}pass("absolute_stream_end_and_unknown_range");}
 static void cancelRead()throws Exception{Source h=new Source(7L);h.holdRead=true;h.holdClose=true;HostInputFactory f=factory(h);HostDataSource ds=f.createDataSource();ds.open(new DataSpec(f.uri()));DefaultExtractorInput in=new DefaultExtractorInput(new HostMp4Inspection.Reader(ds),0,7);byte[] target={9,9};AtomicReference<Throwable> error=new AtomicReference<>();Thread original=new Thread(()->{try{in.readFully(target,0,2);}catch(Throwable t){error.set(t);}},"tester-original-real-input");original.start();try{await(()->h.delayed!=null);ds.close();original.join(2000);need(!original.isAlive()&&error.get() instanceof IOException&&!f.originalsReturned(),"caller returned not same original IO");h.completeRead(2);need(!f.originalsReturned()&&target[0]==9,"original close still pending, late private result not caller");h.closeAck.complete(null);}finally{if(h.delayed!=null&&!h.delayed.isDone())h.completeRead(2);h.closeAck.complete(null);original.join(2000);close(ds,f);}need(Arrays.equals(target,new byte[]{9,9}),"caller untouched");pass("cancel_real_input_late_read_and_close_originals");}
 static void admission()throws Exception{Source h=new Source(7L);HostInputFactory f=factory(h);try{rejected(()->HostMp4Inspection.inspect(f,HostMp4Inspection.Container.MP4,false,-1,false),"MP4_CAPABILITY_UNSUPPORTED");rejected(()->HostMp4Inspection.inspect(f,null,true,-1,false),"MP4_CAPABILITY_UNSUPPORTED");rejected(()->HostMp4Inspection.inspect(f,HostMp4Inspection.Container.MP4,true,-2,false),"MP4_SEEK_BOUNDS");rejected(()->HostMp4Inspection.inspect(f,HostMp4Inspection.Container.MP4,true,2000001,false),"MP4_SEEK_BOUNDS");need(h.opens.get()==0,"before provider open/platform parser");f.createDataSource();f.createDataSource();}finally{f.close();need(f.awaitOriginalReturns(2000),"unused capability returned");}pass("inspection_admission_before_open_and_adapter_allocation");}
 static class ReopenHost extends MemSink {
  final boolean delay;final CountDownLatch work,tail=new CountDownLatch(1);volatile Thread actual;CompletableFuture<AsyncReadBridge.Provider> response;int reopenRPC;
  ReopenHost(boolean d){delay=d;work=new CountDownLatch(d?1:0);}
  public CompletionStage<AsyncReadBridge.Provider> reopenReadOnly(){reopenRPC++;response=new CompletableFuture<>();actual=new Thread(()->{try{work.await();byte[] b=bytes.toByteArray();response.complete(c->CompletableFuture.completedFuture(HostFixtures.memory(b)));tail.await();}catch(InterruptedException e){response.completeExceptionally(e);Thread.currentThread().interrupt();}},"tester-actual-reopen-tail");actual.start();return response;}
  public boolean originalOperationsReturned(){return actual==null||!actual.isAlive();}public boolean writerOriginalsReturned(){return closed;}
  void joinSame()throws Exception{work.countDown();tail.countDown();if(actual!=null){actual.join(2000);need(!actual.isAlive(),"same original reopen thread actually joined");}}
 }
 static void inspectionPending(boolean timeout)throws Exception{ReopenHost h=new ReopenHost(timeout);TemporaryOutput s=new TemporaryOutput(h,false,WORKER,80);try{IndependentFixCheck.written(s);s.finishWriter();rejected(()->s.inspectHostMp4Structure(HostMp4Inspection.Container.FRAGMENTED_MP4),timeout?"OUTPUT_TIMEOUT_PENDING":"OUTPUT_ORIGINAL_PENDING");need(h.reopenRPC==1&&!s.returned(),"same original retained");if(timeout)need("OUTPUT_TIMEOUT_PENDING".equals(s.firstFailure()),"real timeout sticky");else need(s.firstFailure()==null,"pending must not be first business failure");h.work.countDown();await(()->h.response.isDone());s.observeOriginal();rejected(s::finishOriginalCallbacks,"OUTPUT_ORIGINAL_PENDING");h.joinSame();
   if(!timeout){rejected(()->s.inspectHostMp4Structure(HostMp4Inspection.Container.FRAGMENTED_MP4),"OUTPUT_HOST_STRUCTURE_FAILED");need(h.reopenRPC==1&&"OUTPUT_HOST_STRUCTURE_FAILED".equals(s.firstFailure()),"MC-B01 corrected admission now reaches real missing platform boundary");System.out.println("FIX MC_B01 cancelOrAbortBeforeRetry=false sameOriginalThreadReturned=true reopenRPC=1 actualContainer=NOT_RUN");pass("MC_B01_pending_not_sticky_continues_once");}else{rejected(()->s.inspectHostMp4Structure(HostMp4Inspection.Container.FRAGMENTED_MP4),"OUTPUT_NOT_VALIDATABLE");need("OUTPUT_TIMEOUT_PENDING".equals(s.firstFailure())&&h.reopenRPC==1,"true deadline cannot be cleared by late return");pass("inspection_timeout_control_sticky_no_reopen_retry");}
   need(s.abort()&&s.returned()&&h.reopenRPC==1&&h.readies==0&&h.commits==0,"same original cleanup no publication");
  }finally{h.joinSame();s.observeOriginal();if(!s.returned())s.abort();need(s.returned(),"original owner cleanup");}}
 static void invalidRemux()throws Exception{MemSink h=new MemSink();TemporaryOutput s=output(h);try{rejected(()->MatureContainerRemux.writeAndInspect(null,s),"MP4_REMUX_INPUT_UNPROVEN");need(h.writes==0&&h.readies==0&&h.commits==0,"no writer/fixture synthesis from missing evidence");}finally{need(s.abort()&&s.returned(),"no original owner leak on preflight rejection");}pass("remux_missing_evidence_before_writes");}
 public static void main(String[] args)throws Exception{System.out.println("ORIGIN adapter="+HostMp4Inspection.class.getProtectionDomain().getCodeSource().getLocation()+" realInput="+DefaultExtractorInput.class.getProtectionDomain().getCodeSource().getLocation());peek();cumulative();absolute();cancelRead();admission();inspectionPending(false);inspectionPending(true);invalidRemux();need(HostInputFactory.admittedSources()==0&&TemporaryOutput.retained()==0,"all exact owners returned");System.out.println("DONE independentBoundaryPasses="+cases+" reproducedFindings=0 allActualThreadsReturned=true sourceKeepers0 outputKeepers0 realMP4MuxRemux=NOT_RUN");}
}
